// Üretilen dosya: tool/ozgun/uret.py. Sanat · Dekoratif sanatlar: seramik, cam, tekstil, mobilya, kuyumculuk (zor).
const ozArt14Zor = <(String, String, List<String>, String)>[
  ('Temperli camın kırıldığında keskin büyük parçalar yerine küçük kütlecikler hâlinde dağılmasının nedeni nedir?', 'Yüzeyin ani soğutmayla basınç altında, iç kısmın gerilim altında bırakılması', ['Camın içine sıkıştırılmış ince bir plastik tabakanın parçaları bir arada tutması', 'Camın çok ince üretilmiş olması nedeniyle kırıldığında hiç keskin parça vermemesi', 'Camın çok ince üretilmesi'], 'Isıtılan cam hızla soğutulunca yüzey sıkışır, çekirdek gerilir. Kırılma başlayınca depolanan enerji camı çok küçük parçalara ayırır.'),
  ('Üfleme ustasının erimiş camı üfleme borusunun ucuna, ocaktan yığın hâlinde alma işlemine ne ad verilir?', 'Gather', ['Marver', 'Casing', 'Slumping'], 'Usta, borunun ucunu potaya daldırıp bal kıvamındaki cam yığınını alır; buna gather denir. Marver ise yığının üzerinde yuvarlandığı düz tabladır.'),
  ('Cam üflemede, işin borudan koparıldıktan sonra dibine tutturulan ve ağız kısmının şekillendirilmesi için işin ucundan tutulmasını sağlayan çubuğa ne denir?', 'Pontil', ['Parison', 'Kiln', 'Cullet'], 'İş, borudan koparılınca dibine yapıştırılan pontil çubuğuna geçer; böylece ağız kısmı rahatça şekillendirilir. Koparılma izi dipte pontil izi olarak kalır.'),
  ('Cam levhaların fırında yumuşayarak kalıba çökmesiyle şekillendirilmesine (fırın camı işçiliğinde) ne ad verilir?', 'Slumping', ['Gaffing', 'Marvering', 'Wheel cutting'], 'Slumping\'de düz cam bir kalıbın üzerine konup fırında ısıtılır; ağırlığının etkisiyle çöküp kalıbın biçimini alır.'),
  ('Cam fırınlarında cam hamurunu eriten ocağın ağzında usta, çırak ve yardımcıların oluşturduğu çalışma ekibine İngilizce\'de ne ad verilir?', 'Chair', ['Guild', 'Lodge', 'Cartel'], 'Cam atölyesi çalışma birimi \'chair\' adını alır ve başındaki usta \'gaffer\' olarak anılır; geleneksel işbölümü bu ekip düzenine dayanır.'),
  ('Yassı pencere camı üretiminde kullanılan \'taç cam\' (crown glass) yönteminde levha nasıl elde edilir?', 'Üfleme ile oluşan camın hızla döndürülerek disk biçimine açılması', ['Cam hamurunun erimiş hâlde düz bir kalıba dökülüp kendiliğinden donması', 'Yumuşak camın ağır silindirlerin arasından geçirilerek haddelenmesi', 'Cam parçalarının kurşunla birleştirilmesi'], 'Üflenen balon pontile alınıp hızla çevrilince merkezkaç etkisiyle düz bir disk oluşur. Ortası kalın \'bull\'s eye\' kısmı olur.'),
  ('Camın içine örülmüş çapraz beyaz iplikçiklerle ağ görünümü veren Venedik tekniği hangisidir?', 'Reticello', ['Pâte de verre', 'Cameo', 'Bull\'s eye'], '\'Reticello\' (\'küçük ağ\'), karşılıklı yönlerde sarılmış iki sıra iplikçiğin üst üste getirilmesiyle elde edilir; içinde küçük hava kabarcıkları kalır.'),
  ('İsveç\'in Orrefors firmasında Simon Gate ve Edward Hald\'ın geliştirdiği, kalın katmanlı camın oyulup yeniden camla kaplanmasına dayanan teknik hangisidir?', 'Graal', ['Murrine', 'Overshot', 'Ennea'], 'Graal camı, desen oyulduktan sonra üzerine yeni bir cam tabaka daha eklenerek elde edilir. 1916\'dan itibaren İskandinav cam sanatını dünyaya tanıtmıştır.'),
  ('Murano\'da Paolo Venini\'nin 1921\'de kurduğu firmada sanat yönetmenliği yapan ve cam tasarımına geometrik duyarlılık getiren mimar kimdir?', 'Carlo Scarpa', ['Gio Ponti', 'Adolf Loos', 'Aldo Rossi'], 'Carlo Scarpa 1932-1947 arasında Venini\'de çalışarak ince cidarlı ve yalın biçimli camlar tasarlamış; modern Murano camının gelişmesine büyük katkı vermiştir.'),
  ('Pencere camı ve ayna üretiminde 1688\'de Fransız Louis Lucas de Nehou\'nun geliştirdiği \'döküm cam\' yönteminin getirdiği yenilik nedir?', 'Erimiş camın düz masaya dökülüp haddelenerek büyük levhalar elde edilmesi', ['Camın kalıbın içine üflenip çok sayıda eş biçimli parça elde edilmesi', 'Cam parçalarının kurşun şeritlerle birleştirilip pencereye dönüştürülmesi', 'Camın asitle matlaştırılması'], 'Bu yöntem Saint-Gobain\'de uygulanmış ve Versailles\'ın Aynalar Galerisi gibi büyük ayna yüzeylerinin yapımını mümkün kılmıştır.'),
  ('Venedik\'te ayna yapımında cam levhanın arka yüzüne uygulanan ve parlak yansıma veren geleneksel metal kaplama hangisiydi?', 'Kalay-cıva amalgamı', ['Altın varak', 'Bakır sülfat', 'Gümüş nitrat banyosu'], 'Kalay folyo üzerine cıva dökülerek yapılan amalgam, 19. yüzyıla dek ayna yapımında kullanılmıştır. Gümüş kaplamaya Liebig 1835\'te geçmiştir.'),
  ('Eski bir cam avizenin parçaları arasında ışığı güçlü kırıp renk tayfı oluşturan prizmaların bu etkiyi vermesinin fiziksel nedeni nedir?', 'Işığın cam içinde dalga boyuna göre farklı kırılması', ['Camın ışığı tamamen soğurup hiç geçirmemesi ve içinde ısıya dönüştürmesi', 'Camın elektrik yüklü olup ışığı manyetik alan yoluyla saptırması', 'Camın ışığı tamamen geri yansıtması'], 'Her renk camda farklı açıyla kırılır; kesilmiş yüzeyler bu ayrımı büyütür. Kurşun kristalde dispersiyon daha yüksektir.'),
  ('Josiah Wedgwood\'un geliştirdiği ve Kraliçe Charlotte\'a sunulduktan sonra \'Queen\'s Ware\' adını alan krem renkli çanak çömlek ürününün yarattığı etki nedir?', 'Porselen görünümlü ama daha ucuz bir sofra takımının geniş kitlelere ulaşması', ['Çin porselen ithalatının tamamen durup Avrupa\'da kalıcı biçimde yasaklanması', 'Sırsız toprak kapların kullanımının yasaklanıp yerine bakır kapların geçmesi', 'Kıyafet üretiminin hızlanması'], 'Creamware, açık renkli ve hafif gövdesiyle porselene benzedi, çok daha ucuza satılıyordu; böylece İngiliz orta sınıfının sofralarına girdi.'),
  ('Rönesans dönemi Floransa\'da Medici ailesinin desteğiyle 1575 civarında yapılan ve Avrupa\'nın ilk porseleni sayılan ürünlere ne ad verilir?', 'Medici porseleni', ['Delft çinisi', 'Wedgwood jasper', 'Sèvres yumuşak hamuru'], 'Francesco de\' Medici\'nin atölyesinde Çin porselenini taklit etme denemeleri yapıldı; bu parçalar tam sert hamurlu değil, yumuşak hamurlu porselendi ve çok azı günümüze kalmıştır.'),
  ('Bir seramikçi, vazonun yarı kuru yüzeyine ince çizgiler oyup içine koyu renkli kil doldurarak desen oluşturuyor. Bu Kore kökenli tekniğin adı nedir?', 'Sanggam', ['Raku', 'Kintsugi', 'Decalcomania'], 'Kore\'nin Goryeo dönemi seramiklerinde oyma çizgilere beyaz ve siyah kil doldurulur; sır altında zarif bir iç içe geçmiş etki doğar.'),
  ('Seramik fırınında ısıyı doğrudan ölçmek yerine, belirli ısıda yumuşayıp eğilen küçük koni biçimli çubuklar kullanılır. Bunlara ne denir?', 'Seger konileri', ['Raku kaşıkları', 'Kolon çubukları', 'Eritme haddeleri'], 'Her koni belirli bir sıcaklığa ulaşıldığında eğilir; seramikçi fırının ne kadar ısındığını bu eğilmeden anlar.'),
  ('18. yüzyılda Çin\'de pembe ve gül tonlarının yaygınlaştığı, Avrupa ihracat porselenlerinde \'famille rose\' olarak anılan renk paletinin ayırt edici özelliği nedir?', 'Pembe tonları elde etmek için altın içeren renkli emaye kullanılması', ['Yalnızca mavi ve beyaz kullanılması, renkli emayelerin hiç bulunmaması', 'Siyah zemin üzerine yeşil ve kırmızı sırların uygulanması', 'Siyah zemin üzerine yeşil sırın uygulanması'], 'Famille rose, altından elde edilen pembe emaye ile yumuşak renk geçişleri sağlar; Qing döneminde ihracat porselenine büyük talep yaratmıştır.'),
  ('Çin\'de Kangxi döneminde öne çıkan ve yeşili baskın olan renkli emaye porselenine Fransız araştırmacılar hangi adı vermiştir?', 'Famille verte', ['Famille noire', 'Famille jaune', 'Famille bleue'], '\'Famille verte\' (yeşil familya), parlak yeşil, kırmızı, sarı ve mor emayelerle yapılmış, Kangxi (1662-1722) döneminde yaygınlaşmış ihracat ve saray porselenlerini tanımlar.'),
  ('Süt beyazı gövde üzerine ince çizgili kırmızı, turkuaz ve sarı seyrek desenler uygulayan, Avrupa\'da Meissen\'e ilham veren Japon porselen üslubu hangisidir?', 'Kakiemon', ['Imari', 'Seto', 'Kutani'], 'Kakiemon, Arita\'da sakin kompozisyonlarla bezenmiş saydam beyaz zemin üzerinde narin renk lekeleriyle tanınır; Avrupa\'da 17.-18. yüzyıllarda çok taklit edilmiştir.'),
  ('Soluk gökmavisi renkli, ince çatlaklı sırıyla Song döneminde saray için üretilen Ru fırınlarının ürünleri neden çok değerlidir?', 'Çok az sayıda parçanın günümüze ulaşması ve sırın eşsiz güzelliği yüzünden', ['Altın yaldızla süslenmiş ve içine değerli taşlar işlenmiş olmaları yüzünden', 'Avrupa\'da icat edilmiş ve yalnız saraylara ihraç edilmiş olmaları yüzünden', 'Mavi boyanın bilinmemesi yüzünden'], 'Ru porseleninin dünyada yaklaşık yüz kadar örneği bilinir. Yumuşak gökmavisi sırı, Song saray estetiğinin zirvesi sayılır.'),
  ('Abbasi dönemi Irak\'ında (9. yüzyıl) icat edilen, sır üzerine metalik oksit boyayla altın bakır parıltısı veren seramik tekniği sonradan hangi merkezlerde sürdürülmüştür?', 'Fustat (Mısır), Kaşan (İran) ve İspanya', ['Yalnızca Pekin ve Osaka çevresinde, Doğu Asya\'da uygulanmıştır', 'Yalnızca Meissen ve Delft gibi kuzey Avrupa atölyelerinde sürdürülmüştür', 'Başka hiçbir yerde sürdürülmemiş, Abbasi döneminden sonra unutulmuştur'], 'Lüster tekniği Abbasi Irak\'ında doğmuş, Fatımi Mısır\'ında, Selçuklu İran\'ında (Kaşan) ve Endülüs\'te Malaga-Manises\'te yaşatılmıştır.'),
  ('Antik Yunan\'da zeytinyağı saklamaya ve cenaze törenlerinde kullanılan, dar boyunlu ve tek kulplu ince şişenin adı nedir?', 'Lekythos', ['Amphora', 'Krater', 'Pithos'], 'Lekythos, ince boyunlu ve silindirik gövdeli yağ şişesidir; beyaz zeminli lekythoslar çoğunlukla mezarlara bırakılan adak olarak resmedilmiştir.'),
  ('Panathenaia oyunlarında kazananlara zeytinyağı dolu olarak verilen, Athena figürlü büyük amforaların temel özelliği nedir?', 'Hep siyah figür tekniğiyle yapılması ve geleneğin kırmızı figür çağında da sürdürülmesi', ['Hiç boyanmayıp yalnız kabartmayla süslenmeleri ve sırsız bırakılmaları', 'Yalnızca altınla süslenmeleri ve saraya özgü olmaları', 'Çin\'den getirilmeleri'], 'Panathenaik amforalar, yarışmanın ödül kabıydı ve bir bakıma resmî bir gelenek olduğu için eski siyah figür biçimi yüzyıllarca sürdürülmüştür.'),
  ('Antik Roma\'da kırmızı, parlak, sırlıya benzeyen yüzeyi ve kalıpla basılmış kabartmalarıyla bilinen sofra kapları hangi adla anılır?', 'Terra sigillata', ['Mavi-beyaz porselen', 'Raku', 'Majolika'], 'Terra sigillata (\'mühürlü toprak\'), ince kırmızı astarla kaplı seramiktir; Arezzo\'da başlayıp Galya\'da seri üretilmiş ve imparatorluk çapında yayılmıştır.'),
  ('Valencia yakınlarındaki Manises\'te Müslüman çömlekçilerin geliştirdiği ve İtalyan majolikasını etkileyen metalik parlak boyalı seramik türüne ne denir?', 'Hispano-Moresk', ['İstoriato', 'Delft mavisi', 'Jasperware'], 'Hispano-Moresk seramikler, kalay sırı üzerine bakırlı lüsterle altın-kehribar parıltısı verir; İspanya\'dan İtalya\'ya Mayorka adıyla ihraç edilmiş, \'majolika\' adı buradan gelmiştir.'),
  ('Fransızca \'faïence\' sözcüğünün adı, hangi İtalyan kentinden gelmiştir?', 'Faenza', ['Floransa', 'Deruta', 'Venedik'], 'Faenza majolika üretimiyle ün saldığından, kalay sırlı çanak çömlek Fransa\'da \'faïence\' adını almıştır.'),
  ('Aynı vazo üzerinde hem Çin motifleri hem Osmanlı lale desenleri görülürse sanat tarihçisi hangi sonuca varabilir?', 'Kabın, Çin etkisini yorumlayan bir Osmanlı ya da Avrupa atölyesinde yapılmış olabileceğine', ['Kabın kesinlikle Çin\'de, imparatorluk fırınında yapılmış olduğuna', 'Kabın hiçbir atölyede üretilmediğine, tamamen sahte olduğuna', 'Kabın boyasız olduğuna'], 'Lale Osmanlı motifidir; Çin motifi ise başka bir geleneğe işaret eder. İki dilin bir arada görülmesi ihracat veya taklit üretimi düşündürür.'),
  ('Bizans İmparatoru Justinianos\'un 6. yüzyılda ipek yapımını Bizans\'a taşımak için yaptığı hamle nedir?', 'Rahiplerin bambu bastonlar içinde ipek böceği yumurtalarını Çin\'den kaçırması', ['Bizans elçisinin Çin\'den ipek dokuma tezgâhlarını satın alıp getirmesi', 'Dut ağaçlarının Bizans\'ta yasaklanıp ipekçiliğin yalnız ithalatla sürdürülmesi', 'İpek ithalatının kesilmesi'], 'Anlatıya göre iki rahip yumurtaları bastonlarının içinde İstanbul\'a getirdi; böylece Bizans\'ta ipekçilik başladı ve Çin\'in tekeli kırıldı.'),
  ('Edmund Cartwright\'ın 1785\'te patent aldığı \'power loom\' aleti dokumacılığı nasıl değiştirmiştir?', 'Dokumayı el yerine su veya buhar gücüyle çalışan tezgâhlara taşımıştır', ['Pamuğun tarlada makineyle toplanmasını ve balyalanmasını sağlamıştır', 'İpek böceği yetiştirmeyi sera koşullarında hızlandırmıştır', 'Boyama işlemini kolaylaştırmıştır'], 'Güçle çalışan dokuma tezgâhı fabrikalarda kumaş üretimini çok hızlandırmış; el dokumacılarının işsizliği Luddit hareketini körüklemiştir.'),
  ('İlk bakışta aynı görünen iki kumaştan biri el dokuması, diğeri makine dokuması. Tarihçi hangi ipucuna bakarak ayırt edebilir?', 'Kenarlardaki düzensizlik ve iplik kalınlığındaki farklılıklara', ['Yalnızca kumaşın renk tonuna ve parlaklığındaki farka', 'Yalnızca kumaşın üzerindeki etikete ve fiyat bilgisine', 'Sadece fiyatına'], 'El dokumasında iplik kalınlığı ve sıklık hafifçe değişir; kenar çizgisi de makine ürünü kadar düzgün olmaz. Makine ürünü ise çok düzenlidir.'),
  ('Batik ustalarının sıcak mum akıtmak için kullandığı, küçük bir kaba bağlı ince uçlu bakır araca ne ad verilir?', 'Canting (tjanting)', ['Pontil (cam işçiliğinde kullanılan ucu yapışkan çubuk)', 'Kirkit', 'Marver (cam hamurunun üzerinde yuvarlandığı tabla)'], 'Canting, içine mum konan küçük haznesi ve ince borusuyla çizgiyi kumaşa akıtır; geniş alanlar ise \'cap\' adlı bakır damgayla kapatılır.'),
  ('Hindistan\'ın Gujarat bölgesine özgü, kumaşın küçük noktalar hâlinde bağlanıp boyanmasıyla elde edilen desen türü hangisidir?', 'Bandhani', ['Kalamkari', 'Zardozi', 'Paisley'], 'Bandhani\'de binlerce küçük nokta iplikle sıkıca bağlanır; boyanınca bağlanmış kısımlar beyaz kalır, noktalar halinde desen oluşur.'),
  ('Çuha ya da keten kumaşın indigo boyasıyla maviye boyanmasında kumaş kazandan çıkarıldığında rengin kısa sürede maviye dönmesinin nedeni nedir?', 'Çözünmüş indigonun havadaki oksijenle tepkimeye girmesi', ['Güneşten gelen morötesi ışınların boyayı kumaşta yeniden üretmesi', 'Kumaşın soğuyarak büzülmesi', 'Boyaya katılan tuzun kumaşta kristalleşmesi ve kuruması'], 'İndigo suda çözünmesi için indirgenir (sarı-yeşil); lif havaya çıkınca oksitlenir ve çözünmeyen mavi pigmente dönüşür.'),
  ('Fransa\'da Oberkampf\'ın 1760\'ta Jouy-en-Josas\'ta başlattığı, tek renkli pastoral sahneli pamuklu kumaşa verilen ad nedir?', 'Toile de Jouy', ['Chintz', 'Damask', 'Brokar'], 'Toile de Jouy, bakır plakayla basılan, genellikle beyaz zemin üzerine kırmızı ya da mavi tek renkli köy hayatı sahneleriyle ünlü bir mobilya ve perde kumaşıdır.'),
  ('William Morris\'in 1883\'te indigo boşaltma yöntemiyle bastırdığı, meyve çalan ardıçkuşlarını gösteren ünlü kumaş deseninin adı nedir?', 'Strawberry Thief', ['Unikko', 'Honeysuckle Chain', 'Peacock Garden'], 'Strawberry Thief, Morris\'in Merton Abbey atölyesinde elle bastırılan en karmaşık desenlerindendir; indigo ile boşaltma yöntemi kumaşı zorlu bir işlemden geçirir.'),
  ('Londra\'da 1875\'te kurulan mağazada Doğu kumaşları satan ve baskılı desenleriyle Art Nouveau\'nun kumaş zevkini belirleyen firma hangisidir?', 'Liberty', ['Marimekko', 'Gobelins', 'Wedgwood'], 'Arthur Lasenby Liberty\'nin mağazası Doğu kumaşları ve Arts and Crafts desenleriyle tanındı; \'Liberty print\' adı hâlâ çiçek desenli pamuklular için kullanılır.'),
  ('Hindistan\'da kalem ve bitkisel boyalarla kumaşa elle çizilen ya da blokla basılan, Andhra Pradesh bölgesine özgü anlatı kumaşlarına ne denir?', 'Kalamkari', ['Bandhani', 'Shibori', 'Suzani'], 'Kalamkari, Farsça \'kalem işi\' demektir; Hint destanlarından sahneler ya da bitkisel desenler doğal boyalarla kumaşa işlenir.'),
  ('Papa X. Leo\'nun Sistina Şapeli için 1515\'te sipariş ettiği gobelenlerin Raffaello tarafından hazırlanan yaklaşık yedi kartonu bugün hangi müzede sergilenmektedir?', 'Londra\'daki Victoria ve Albert Müzesi', ['Louvre Müzesi', 'Prado', 'Vatikan Müzeleri'], 'Gobelenler Brüksel\'de dokundu; Raffaello\'nun boyalı kartonlarından günümüze ulaşan yedisi, Kral I. Charles tarafından alındıktan sonra bugün V&A\'da korunur.'),
  ('Orta Çağ İngiltere\'sinin altın ve gümüş ipliklerle yapılmış ipek nakışına verilen, Avrupa\'da çok aranan adı nedir?', 'Opus Anglicanum', ['Opus Sectile', 'Opus Reticulatum', 'Opus Francigenum'], '13-14. yüzyıl İngiliz nakışı Avrupa\'nın dört bir yanında aranırdı; Papalık hazinelerinde bile örnekleri bulunur. Ağırlıklı olarak dinî giysilere işlenirdi.'),
  ('Bengal\'de eski sari ve dhotilerin birkaç kat üst üste dikilerek yorgan haline getirilmesi geleneğinin adı nedir?', 'Kantha', ['Suzani', 'Hardanger', 'Petit point'], 'Kantha, atılmayan eski kumaşları katmanlayıp ince koşu dikişiyle birleştirmeye dayanır; dikişler hem kumaşı tutar hem desen oluşturur.'),
  ('Venedik\'te 16. yüzyılda ünlenen ve tek iğneyle dikilerek ince ilmeklerden oluşan dantel türüne ne ad verilir?', 'İğne dantelisi (punto in aria)', ['Bobin dantelisi (çok sayıda iplik masurayla örülür)', 'Makrome', 'Tül dantel (makine ağı üzerine işlenen dantel)'], 'İğne danteli, çizilmiş bir desen üzerinde tek iğneyle ilmekler yapılarak elde edilir. Bobin dantelinde ise çok sayıda iplik masuralarla örülür.'),
  ('Antik Roma\'da yüksek rütbeli magistratların kullandığı, X biçimli katlanır sandalyenin adı nedir?', 'Sella curulis', ['Triclinium', 'Cathedra', 'Lectus'], 'Sella curulis, konsül ve praetor gibi görevlilerin gücünü simgeleyen, fildişi ayaklı katlanır tahttı; taşınabilir olması görev yerinde kurulmasını kolaylaştırıyordu.'),
  ('Thomas Chippendale\'in 1754\'te yayımlanan ünlü mobilya model kitabının adı nedir?', 'The Gentleman and Cabinet-Maker\'s Director', ['The Cabinet-Maker and Upholsterer\'s Guide', 'The Cabinet-Maker and Upholsterer\'s Drawing Book', 'The Cabinet-Maker\'s Drawing Book'], 'Chippendale\'in kitabı, Rokoko, Gotik ve Çin üsluplarında tasarımlar içerir; İngiliz mobilya modasının yayılmasında etkili olmuştur.'),
  ('Almanya ve Avusturya\'da 1815-1848 arasında yükselen orta sınıf zevkine uygun, sade ve konforlu mobilya üslubu hangisidir?', 'Biedermeier', ['Rokoko', 'Art Nouveau', 'Brutalizm'], 'Biedermeier mobilyası, açık renkli kiraz ve ceviz kaplamayla düz hatları, ölçülü süsüyle sarayın değil, konutun ve orta sınıfın zevkini yansıtır.'),
  ('Bir mobilya uzmanı, çekmece kenarında elle kesilmiş düzensiz kırlangıç kuyruğu eklemleri gördüğünde ne düşünür?', 'Parçanın el yapımı ve muhtemelen eski olduğunu', ['Parçanın mutlaka sahte olduğunu ve yakın zamanda taklit üretildiğini', 'Parçanın plastik kalıpla basılmış, fabrika ürünü olduğunu', 'Fabrikada lazer kesim yapıldığını'], 'El kesimi eklemlerde aralıklar ve kalınlıklar hafifçe değişir; makineyle kesilmiş olanlar tamamen düzenlidir. Bu ayrıntı mobilya tarihlendirmesinde ipucudur.'),
  ('Hollandalı mimar Mart Stam\'ın 1926\'da tasarladığı ve arka ayağı olmadan yalnız çelik borulara dayanan sandalyenin yeniliği nedir?', 'İlk konsol (ayaksız) sandalye fikri', ['İlk tamamen plastikten yapılmış sandalye fikri ve kalıp dökümü', 'İlk katlanabilen ve taşınabilir kamp sandalyesi tasarımı', 'İlk yaldızlı sandalye'], 'Stam, gaz borularını birleştirerek arka ayağı olmayan, havada duruyor görünümlü bir sandalye ortaya koydu; bu fikir Breuer ve Mies tarafından geliştirildi.'),
  ('Harry Bertoia\'nın 1952\'de ürettiği \'Diamond\' sandalyesinin farkı hangisidir?', 'Kaynaklı tel örgüden yapılmış, heykel görünümlü gövdesi', ['Elle oyulmuş masif ahşap gövdesi ve süslemeli sırtlığı', 'Tamamen camdan yapılmış, saydam ve çok kırılgan gövdesi', 'Katlanabilen ve kolayca taşınabilen, kumaş gerilmiş iskeleti'], 'Bertoia, tel örgüyü heykel gibi biçimlendirdi; Diamond sandalyesi, hafif ve içi boş görünümüyle mobilya ile heykel arasındaki sınırı bulanıklaştırmıştır.'),
  ('Çin ve Japonya\'da oda bölmek için kullanılan, katlanabilir panolu ve çoğunlukla resimli ya da lake paravanlara ne ad verilir?', 'Byōbu (Japonca) / Pingfeng (Çince)', ['Rahle (Kur\'an ve kitap okumak için kullanılan katlanır sehpa)', 'Sedir (Türk evinin duvar boyunca uzanan oturma elemanı)', 'Cassone (Rönesans İtalya\'sının boyalı çeyiz sandığı)'], 'Byōbu, Japonya\'da altın yapraklı ya da mürekkepli resimlerle süslü paravandır; Çin\'deki karşılığı pingfeng\'dir. Sedir ise Türk evinin oturma elemanıdır.'),
  ('Edirne\'de ahşap eşya ve tavan süslemelerine uygulanan, boyalı ve vernikli geleneksel süsleme tekniğine ne ad verilir?', 'Edirnekâri', ['Kündekâri', 'Sedefkâri', 'Tombak'], 'Edirnekâri, adını Edirne\'den alır; çiçek ve meyve gibi motiflerin ahşap üzerine boyanıp vernikle kaplanmasıyla yapılır.'),
  ('Bir tasarımcı, Jacobsen Ant ile Panton sandalyesini karşılaştırıyor. İkisinin üretim yöntemi bakımından ortak yönü nedir?', 'İkisinin de kalıpla biçimlendirilen tek parça kabukla seri üretime elverişli olması', ['İkisinin de usta elleriyle oyularak, tek bir ağaç gövdesinden yapılması', 'İkisinin de tamamen doğal taştan yontulup elle parlatılması', 'İkisinin de çivi ve zıvana ile geleneksel biçimde birleştirilmesi'], 'Ant kalıplanmış kontrplak, Panton ise kalıplanmış plastik gövdeyle yapılır; ikisi de endüstri tasarımının kalıp ve seri üretim yöntemlerine dayanır.'),
  ('Platin adının İspanyolca kökeni nedir ve bu ad ne anlama gelir?', '\'Platina\': \'küçük gümüş\'', ['\'Platino\': \'sarı altın\' anlamına gelen, Antik Mısır kaynaklı bir sözcük', '\'Plata\': \'bakır cevheri\'', '\'Plat\': \'sert taş\''], 'Güney Amerika\'da bulunan platin, İspanyollarca gümüşe benzetilerek \'küçük gümüş\' anlamına gelen \'platina\' diye adlandırıldı.'),
  ('İngiltere\'de değerli madenlerin saflığını doğrulayan resmî damgaya \'hallmark\' denmesinin nedeni nedir?', 'Damganın vurulduğu Londra\'daki Goldsmiths\' Hall\'dan gelmesi', ['Damga ustasının adından ve ustanın doğduğu kentin adından gelmesi', 'Damganın dairesel olması', 'Damganın saraydan çıkması'], '\'Hallmark\' sözcüğü, ayar damgalarını vuran Goldsmiths\' Hall\'a (Kuyumcular Salonu) işaret eder; damga saflığı garanti eder.'),
  ('Kuyumculukta niello tekniğinde siyah dolgu maddesi nasıl uygulanır?', 'Gümüş üzerine oyulmuş çizgilere eritilmiş siyah metal sülfür karışımı doldurulur', ['Camdan yapılmış çok ince tozlar sürülüp fırında sırlanır', 'Mum tabaka sürülüp boyanır', 'Sedef parçalar yapıştırılır'], 'Niello, gümüş, bakır ve kurşun sülfürlerinden oluşan siyah bir alaşımdır; oyuklara erimiş hâlde doldurulur ve cilalanınca gümüşün parlak yüzeyiyle güçlü bir zıtlık yaratır.'),
  ('Kloazone mine, ince metal şeritlerle bölmeler yapılıp renkli camsı mine ile doldurulan tekniktir. Bu bölmelerin adı nedir?', 'Cloisons', ['Pavé', 'Bezel', 'Chaton'], '\'Cloison\' bölme demektir; ince şeritler zemine lehimlenip aralarına mine tozu doldurulur ve fırınlanır. Bizans ve Orta Çağ kuyumculuğunda yaygındır.'),
  ('Arkasında metal zemin bulunmayıp ışığın içinden geçmesini sağlayan, vitray görünümlü mine tekniğine ne ad verilir?', 'Plique-à-jour', ['Basse-taille', 'Guilloché', 'Limoges mine'], 'Plique-à-jour\'da metal bölmeler arasında zemin yoktur; mine dolgu ışığı geçirir. Art Nouveau mücevherinin, özellikle Lalique\'in en etkileyici tekniklerinden biridir.'),
  ('Güney Afrika\'da Kimberley bölgesinde 1870\'lerde elmas keşfi ve De Beers şirketinin kurulması, elmas piyasasını nasıl etkilemiştir?', 'Arzı artırıp elmas üretimini sanayi ölçeğine taşımıştır', ['Elmas ticaretini tamamen durdurmuş ve elmasın fiyatını sıfıra indirmiştir', 'Elması renkli cama dönüştürmüştür', 'Elmasın ancak saraylarda bulunmasını sağlamıştır'], 'Kimberley keşiflerinden sonra elmas bol hâle geldi; Cecil Rhodes\'un 1888\'de kurduğu De Beers arzı kontrol ederek fiyatı yüksek tuttu.'),
  ('Irak\'taki Ur Kraliyet Mezarları\'nda (yaklaşık MÖ 2600) bulunan Kraliçe Puabi\'nin başlığı hangi malzemelerle yapılmıştır?', 'Altın yapraklar, lapis lazuli ve karnelyan', ['Gümüş telleri, mercan boncukları ve sedef kakmalardan oluşan bir örgü', 'Bronz, cam ve fildişi', 'Yeşim, kehribar ve inci'], 'Leonard Woolley\'nin kazılarında çıkan kraliçe başlığı, altın söğüt yapraklarını lapis lazuli ve karnelyan boncuklarla birleştirir; Sümer kuyumculuğunun en parlak örneklerindendir.'),
  ('Heinrich Schliemann\'ın 1873\'te Hisarlık\'ta (Troya) bulduğunu duyurduğu ve Priamos\'un hazinesi diye adlandırdığı altın takılar hangi nedenle tartışmalıdır?', 'Hazinenin izinsiz yurt dışına çıkarılması ve tarihinin Homeros\'tan çok eski olması', ['Altının sahte olduğunun sonradan laboratuvarda kanıtlanması ve Mısır\'dan getirilmiş olması', 'Hazinenin Mısır\'dan getirilmesi', 'Hazinenin Roma çağına ait olması'], 'Hazine Troya II tabakasından çıkmış (MÖ 2500 dolayı) ve Homeros\'un anlattığı Priamos\'tan yaklaşık bin yıl eskidir; Schliemann bunu Osmanlı\'dan gizleyerek yurt dışına taşımıştır.'),
  ('İngiltere\'deki Sutton Hoo gemi mezarında (1939) bulunan 7. yüzyıl Anglo-Sakson takılarının dikkat çeken tekniği nedir?', 'Altın üzerine kırmızı garnet kakma', ['Altın üzerine yeşil sır uygulanıp fırınlanarak elde edilen camsı bir yüzey', 'Gümüş üzerine mine boyama', 'Altın üzerine fildişi oyma'], 'Sutton Hoo\'daki kemer tokaları ve omuz bağlantıları, ince altın bölmelere yerleştirilmiş kırmızı garnetlerle bezelidir; garnet muhtemelen Hindistan ve Sri Lanka\'dan gelmiştir.'),
  ('1904\'te Kopenhag\'da kurulan ve yalın kıvrımlı gümüş eşya ve mücevherleriyle İskandinav tasarımına katkıda bulunan atölye hangisidir?', 'Georg Jensen', ['Orrefors', 'Royal Copenhagen', 'Marimekko'], 'Georg Jensen, önce heykeltıraş ve seramikçiydi; gümüşe kıvrımlı organik biçimler vererek zanaat ile Art Nouveau\'yu birleştirdi.'),
  ('Topkapı Sarayı\'nda bulunan ve 1747\'de İran Şahı Nadir Şah\'a hediye edilmek üzere yapılan ünlü hançerin sapında hangi değerli taşlar öne çıkar?', 'Üç büyük zümrüt ve elmas', ['Üç büyük inci ve altın zincirle bağlanmış sedef kakmalar', 'Üç büyük safir', 'Üç büyük yakut'], 'Hançer, I. Mahmud tarafından Nadir Şah\'a gönderilmek üzere hazırlandı; Nadir Şah öldürülünce hediye İstanbul\'a döndü. Sapı ve kını zümrüt ve elmaslarla bezelidir.'),
  ('Osmanlı sarayında kuyumcubaşının görevi neydi?', 'Saray kuyumcuları topluluğunun başında olup mücevher ve değerli eşya yapımını yönetmek', ['Hazine kayıtlarını tutmak ve hazineye giren her değerli eşyayı sayarak teslim almak', 'Sikke basmak', 'Sarayın yemeklerini hazırlamak'], 'Saray Enderun\'daki kuyumcular ocağının başkanı olan kuyumcubaşı, padişahın mücevher ve süs eşyası siparişlerini yönetirdi.'),
  ('Japon kılıçlarında el ile kılıç bıçağı arasında yer alan koruma plakasına ne ad verilir?', 'Tsuba', ['Netsuke', 'Inro', 'Kabuto'], 'Tsuba, savaşçının elini koruyan, çoğunlukla demirden yapılan ve kabartma, kakma gibi inceliklerle süslenmiş kılıç muhafazasıdır.'),
  ('Çin\'in Shang dönemi (MÖ 2. binyıl) bronz ritüel kaplarının yüzeyinde sık görülen, iri gözlü hayvan yüzü biçimli motifin adı nedir?', 'Taotie', ['Ruyi', 'Gulong', 'Fenghuang'], 'Taotie, simetrik, gözleri belirgin bir canavar yüzüdür; Shang döneminde ata kültü için kullanılan bronz kaplarda yoğun biçimde görülür.'),
  ('Çin\'de Shang bronzlarının üretiminde başlıca kullanılan döküm yönteminin özelliği nedir?', 'Seramik kalıp parçalarının birleştirilip içine erimiş bronz dökülmesi', ['Mum modelin kalıba gömülüp eritilmesi ve yerine metalin dökülmesi', 'Metalin taştan oyulması', 'Bronzun soğuk hâlde dövülmesi'], 'Shang ustaları kil kalıp parçalarını birleştirip bronzu içine döktüler; bu yöntem çok ince ve karmaşık yüzey desenlerini kaplara aktarabilirdi.'),
  ('Çin\'de Jingtai döneminde (15. yüzyıl) yaygınlaşan ve \'Jingtailan\' adıyla anılan eşya hangi tekniğe dayanır?', 'Bakır gövde üzerine mavi mine dolgulu kloazone', ['Seramik gövde üzerine mavi sır uygulanıp sıraltı boyamayla süslenmesi', 'Lak üzerine altın serpme', 'Yeşim üzerine kabartma oyma'], 'Jingtai\'nin parlak mavi kloazone minesi, Çin sanatının Ming dönemindeki en zarif metal işçiliklerindendir; bölmeler altın yaldızlı bakır tellerdir.'),
  ('Çin\'den Avrupa\'ya ihraç edilen ve oyma lake paravanlar için kullanılan \'Coromandel\' adı hangi bölgeden gelir?', 'Güneydoğu Hindistan\'daki Coromandel kıyısından', ['Çin\'in güneydoğusundaki Guangzhou limanında bulunan ticaret merkezinden', 'Japonya\'nın Kyoto kentinden', 'Hollanda\'nın Delft kentinden'], 'Çin paravanları Avrupa\'ya Hindistan\'ın Coromandel kıyısındaki limanlardan taşındı; Avrupalılar bu paravanlara limanın adını verdi.'),
  ('1588\'de Floransa\'da Medici Büyükdükü I. Ferdinando\'nun kurduğu ve sert taş parçalarıyla resim yapma geleneğini sürdüren atölye hangisidir?', 'Opificio delle Pietre Dure', ['Gobelins Manufakturası', 'Meissen', 'Wiener Werkstätte'], 'Bu atölye, renkli sert taş parçalarını kesip birleştirerek masa tablaları ve paneller yapar (commesso). Sanat bugün hâlâ restorasyon alanında sürmektedir.'),
  ('Fransa\'da 18. yüzyılda Martin kardeşlerin geliştirip kraliyet onayıyla ünlenen, Doğu lakesini taklit eden vernikli işlere ne ad verilir?', 'Vernis Martin', ['Gesso', 'Ormolu', 'Craquelé'], 'Vernis Martin, açık renkli ve cilalı vernik olarak kareta, mobilya ve küçük eşyalarda kullanılmış; adı Martin ailesinden gelir.'),
  ('Owen Jones\'un 1856\'da yayımlanan \'The Grammar of Ornament\' kitabının dönemin tasarımcılarına başlıca katkısı nedir?', 'Dünya kültürlerinden bezeme örneklerini renkli çizimlerle sistemli biçimde sunması', ['Yalnız Rönesans resimlerini kuramsal biçimde incelemesi ve tasarımdan söz etmemesi', 'Cam üflemeyi anlatması', 'Mimariyi tamamen reddetmesi'], 'Kitap, Mısır\'dan Çin\'e dünya bezeme sanatlarının örneklerini renkli litografilerle derleyip genel ilkelerini sıraladı; Victoria dönemi tasarımcılarının temel başvuru kaynağı oldu.'),
  ('Gottfried Semper\'in \'kaplama (Bekleidung) kuramı\'na göre, mimarlık ve dekoratif sanatların kökeninde hangi zanaat yer alır?', 'Dokuma ve örgü (tekstil)', ['Seramik (çömlekçilik ve fırın işçiliği)', 'Cam üfleme', 'Taş oyma'], 'Semper, mekân sınırlarının önce çit ve hasır örgüsüyle oluştuğunu, duvarların da sonradan bu örtünün katılaşmış biçimi olduğunu savundu; bu görüş süsleme anlayışını etkiledi.'),
  ('James McNeill Whistler\'ın 1876-77\'de Londra\'da Frederick Leyland\'ın yemek odası için tasarladığı, mavi ve altın tonlu bezemeli iç mekân hangi adla anılır?', 'Peacock Room (Tavus Kuşu Odası)', ['Red House (Morris\'in Bexleyheath\'teki tuğla evi)', 'Willow Tea Rooms', 'Hill House'], 'Peacock Room, Aesthetic Movement\'ın (\'sanat sanat içindir\') en bilinen iç mekânıdır. Bugün Washington\'daki Freer Galerisi\'nde korunmaktadır.'),
  ('Art Nouveau adının kaynağı olan, Siegfried Bing\'in 1895\'te Paris\'te açtığı mağaza hangisidir?', 'Maison de l\'Art Nouveau', ['Salon des Refusés', 'Café Guerbois', 'Galerie Vivienne'], 'Bing\'in mağazası, Japon sanatı ve yeni tasarımları sergiledi; mağazanın adı sonradan akımın adı hâline geldi.'),
  ('1913\'te Roger Fry\'ın Londra\'da Bloomsbury çevresindeki sanatçılarla kurduğu, mobilya, seramik ve kumaş atölyesinin adı nedir?', 'Omega Workshops', ['Guild of Handicraft', 'Wiener Werkstätte', 'Deutscher Werkbund'], 'Omega\'da Vanessa Bell ve Duncan Grant gibi ressamlar eşya tasarladı; ürünler imzasız satılarak sanatçıların adından çok tasarıma önem verildi.'),
  ('Marianne Brandt\'ın Bauhaus metal atölyesinde 1924\'te tasarladığı MT 49 çay demliği, tasarım tarihinde neden önemlidir?', 'Küre, silindir ve daire gibi temel geometrik biçimleri sanayi üretimine uygun ürüne dönüştürmesi', ['Altın yaldızlı rokoko süslerini yeniden canlandırıp saraylara sunması', 'Ahşap oymacılığının sürdürülmesi', 'El dövmesi bakır işçiliğini yüceltmesi'], 'Brandt, çay demliğini yalın geometrik biçimlerle ve parlak metallerle tasarlayıp seri üretime uygun hâle getirdi; ürün Bauhaus\'un işlevsel estetiğinin simgesidir.'),
  ('Bauhaus\'ta Wilhelm Wagenfeld ve Karl J. Jucker\'in 1924\'te tasarladığı masa lambasının ayırt edici özelliği nedir?', 'Cam gövde, metal ayak ve yalın geometrik biçimle tasarlanmış olması', ['Altın yaldızlı, oymalı ve kıvrımlı sarmaşık biçimli gövdesi', 'Seramik ayağı', 'Kâğıt abajuru'], 'Bauhaus lambası, cam silindir ve küre ile metal ayağın birleşimidir; ekonomik, işlevsel ve seri üretilebilir tasarım düşüncesinin ürünüdür.'),
  ('Fransız saray iç mekânlarında duvarlara uygulanan, oyma ahşap lambri ve kaplamalara ne ad verilir?', 'Boiserie', ['Azulejo', 'Stuko', 'Parquet'], 'Boiserie (ahşap kaplama), Barok ve Rokoko iç mekânlarında duvarın alt bölümünü ya da tamamını kaplayan panolardır; çoğunlukla boyalı ve yaldızlı bezeme taşır.'),
  ('Versailles Sarayı\'ndaki Aynalar Galerisi\'nin bir ucunda 17 aynalı pencere varsa karşı duvardaki ayna dizisinin amacı nedir?', 'Pencerelerden gelen ışığı ve bahçeyi yansıtarak galeriyi genişlik ve ışıkla doldurmak', ['Sarayı yazın serinletmek ve ortamdaki ısıyı havalandırma yoluyla dağıtmak', 'Düşman gözetlemesi', 'Müzik akustiğini bozmak'], 'Karşılıklı 17 pencereyi yansıtan 357 ayna, uzun koridora ışık ve derinlik katar; 1680\'lerde büyük aynaların pahalılığı da XIV. Louis\'nin gücünü gösterirdi.'),
  ('Orta Çağ\'ın dinî eşyalarında bakır üzerine renkli mine tozlarıyla yapılan ve 12. yüzyılda Fransa\'nın bir kentinde ünlenen işçiliğin merkezi neresidir?', 'Limoges', ['Marsilya', 'Lyon', 'Nancy'], 'Limoges, 12-13. yüzyılda sunak haçları, rölikerler ve kaplar üzerindeki renkli şamplöve mineleriyle Avrupa\'ya ihracat yapan bir merkezdi.'),
  ('Japonya\'da Soetsu Yanagi\'nin öncülüğünde, anonim ustaların günlük kullanım eşyalarındaki güzelliği öne çıkaran halk zanaatı hareketinin adı nedir?', 'Mingei', ['Ukiyo-e', 'Shibori', 'Wabi'], 'Mingei, \'halkın sanatı\' demektir; Shoji Hamada ve Leach bu anlayışı çömlekçiliğe taşıdı. Kullanım nesnesinin yalın güzelliği amaçlanır.'),
  ('Viyana doğumlu olup 1938\'de Londra\'ya göç eden ve ince cidarlı porselen vazoları, volkanik benzeri sırlarıyla tanınan seramikçi kimdir?', 'Lucie Rie', ['Grayson Perry', 'Shoji Hamada', 'Peter Voulkos'], 'Lucie Rie, modern stüdyo seramiğinin en zarif isimlerindendir; sade kâse ve şişe biçimlerini kendine özgü sırlarla süsledi.'),
  ('Joan Miró ile seramikçi Josep Llorens Artigas\'ın 1958\'de birlikte yaptığı, Paris\'te UNESCO binası bahçesinde yer alan eserlerin adı nedir?', 'Güneş ve Ay Duvarları', ['Guernica Panosu', 'Kırmızı Atlar Frizi', 'Cam Piramit'], 'Miró\'nun resimsel hayal gücü ve Artigas\'ın fırın bilgisi, seramik duvar panolarında birleşmiştir; çalışma, seramiğin anıtsal sanat olarak kabulüne katkıda bulunmuştur.'),
  ('Peter Voulkos\'un 1950\'lerde seramiği soyut dışavurumcu bir üslupla ele almasının önemi nedir?', 'Seramiği kullanım nesnesi olmaktan çıkarıp heykel gibi ele alması', ['Seramiği tamamen bırakıp yalnız cam ve metal işlemeye yönelmesi', 'Seramiği yalnız endüstride kullanması', 'Seramiği camla değiştirmesi'], 'Voulkos kili hızla ve cesurca biçimlendirip yırtık, kabaca delinmiş formlar yaptı; seramik kaba dönüşü yerine heykelsi ifade sanatı olarak yorumlandı.'),
  ('Grayson Perry\'nin 2003\'te Turner Ödülü almasının sanat dünyası için anlamı nedir?', 'Seramik vazoların çağdaş sanatın en prestijli ödüllerinden biriyle ödüllendirilmesi', ['Cam ürünlerinin ilk kez aynı ödülle ödüllendirilmesi ve resmin geri plana itilmesi', 'Resmin ölümünün ilan edilmesi', 'Fotoğrafın yasaklanması'], 'Perry, geleneksel vazo biçimlerini toplumsal eleştiri ve kişisel anlatıyla yüklü resimlerle süslemiş; seramiğin zanaat değil çağdaş sanat olduğunu hatırlatmıştır.'),
  ('Marc Chagall\'ın 1960\'lardaki vitray çalışması arasında yer alan ve İsrail\'in on iki kabilesini temsil eden pencereler hangi kurumdadır?', 'Kudüs\'teki Hadassah Tıp Merkezi sinagogu', ['Reims Katedrali\'nin doğu apsisindeki pencereler', 'Paris Notre-Dame', 'Zürih Kunsthaus'], 'Chagall\'ın on iki penceresi, Yakup\'un oğullarını ve İsrail kabilelerini temsil eder; parlak mavi, kırmızı ve sarı tonlarıyla modern vitray sanatının önemli eseridir.'),
  ('Henri Matisse\'in yaşamının son yıllarında tasarlayıp 1951\'de açılan Vence\'deki şapelin en dikkat çeken sanatsal özelliği hangisidir?', 'Mavi, yeşil ve sarı sade vitraylar ile beyaz duvarlar arasındaki ışık oyunu', ['Altın yaldızlı duvar resimleri ve ağır oymalı ahşap sunak', 'Barok tavan resimleri', 'Gotik sivri kemerli pencereler'], 'Vence\'deki Rozer Şapeli\'nde Matisse, vitrayları ve beyaz seramik panoları ışıkla çalışan yalın bir kompozisyona dönüştürdü; eserini \'başyapıtım\' diye niteledi.'),
  ('Vitrayda renkli cam tabakasının ince bir tabaka olarak renksiz camın üzerine kaplandığı türe ne ad verilir?', 'Flashed glass (kaplamalı cam)', ['Pot metal (rengin cam hamurunun tüm kalınlığına katıldığı tür)', 'Lampwork', 'Reticello'], 'Kırmızı gibi çok koyu renkler tam kalınlıkta çok kapalı olacağından, ince renkli tabaka renksiz cam üzerine kaplanır; aşındırılarak desen de verilebilir.'),
  ('İngiltere\'de 14. yüzyılda yün ticaretine verilen önemi simgeleyen ve Lordlar Kamarası\'nda Lord Şansölye\'nin oturduğu yün dolu minder hangi adla bilinir?', 'Woolsack', ['Cloth Hall', 'Merino', 'Spinning Jenny'], 'Woolsack, yünün İngiltere ekonomisinin temel dayanağı olduğunu hatırlatan geleneksel bir sembol olarak bugün de Lordlar Kamarası\'nda yer alır.'),
  ('17. yüzyıl sonunda Londra\'nın Spitalfields semtini ipek dokumacılığının merkezi hâline getiren topluluk hangisidir?', 'Fransa\'dan göç eden Huguenot dokumacılar', ['Almanya\'dan gelen madenciler ve demir ustaları topluluğu', 'Osmanlı tüccarları', 'İtalyan seramikçiler'], 'Fransız Protestan Huguenotlar, 1685\'ten sonra göç ederek Spitalfields\'de ipek tezgâhları kurdular; bu çevre sonradan İngiliz tasarım zevkini etkiledi.'),
  ('İngiltere\'de 1700 ve 1721\'de çıkarılan Calico Yasaları\'nın amacı neydi?', 'Hint pamuklularının ithalatı ve kullanımını kısıtlayıp yerli yün ve ipek üretimini korumak', ['Yerli pamuk ekimini teşvik edip pamuklu ihracatını artırmak', 'Kumaş vergilerini kaldırmak', 'Hint ipeğini serbest bırakmak'], 'Hindistan\'dan gelen ucuz, boyalı pamuklular yerli yün ve ipek dokumacılarını tehdit ediyordu; yasalar bu rekabeti sınırlamaya çalıştı, ancak yerli pamuklu sanayisinin gelişmesini de tetikledi.'),
  ('Japonya\'da Kyoto\'nun Nishijin bölgesi hangi dokuma türüyle ünlüdür?', 'Altın ve gümüş iplikli brokar kimono kumaşları', ['Pamuklu denim', 'Keçe', 'Dantel'], 'Nishijin-ori, Kyoto\'da saray ve soylular için dokunan çok renkli, metal iplikli ağır ipek kumaşlardır; obi (kuşak) yapımında da kullanılır.'),
  ('Çin\'in Suzhou kentinin ünlü nakış geleneğinin ayırt edici özelliği nedir?', 'Ipeğe çok ince iplikle, iki yüzü de aynı biçimde nakış işlenmesi', ['Yünle kalın dikiş atılması ve kumaşın bir yüzünün düz bırakılması', 'Sadece kırmızı iplik', 'Sadece boncuk dikme'], 'Suzhou nakışında ince ipek iplik ayrıştırılarak işlenir; çift yüzlü nakışlarda iki yüz de ön yüz gibi görünür.'),
  ('Gaziantep\'te dokunan, ipek ve pamuk karışımlı, çizgili ve parlak geleneksel kumaşın adı nedir?', 'Kutnu', ['Kemha', 'Seraser', 'Çatma'], 'Kutnu, Gaziantep ve Antep bölgesinde geleneksel olarak dokunur; genellikle ipek çözgü ve pamuk atkıdan, çoğunlukla çizgili desenli parlak kumaştır.'),
  ('Bir kilise pencerelerinde yer yer renklerin solmuş, bazı alanlarda boyanın kabarıp döküldüğü fark ediliyor. Vitray restoratörü hangi sonuca varabilir?', 'Yüzeye uygulanan boyanın zamanla çatlayıp ayrıldığını', ['Camın fırınlanmadan doğrudan boyanması ve bu yüzden boyanın dökülmesi', 'Pencerenin yeni yapıldığını', 'Kurşunun erimiş olduğunu'], 'Fırınlanmış boyaların bile uzun yıllar nem ve ısı değişimiyle ayrılabileceği, camın içine eritilmiş rengin ise daha dayanıklı olduğu bilinir.'),
  ('1902\'de Auguste Verneuil\'in alev ergitme yöntemiyle ilk kez ticari ölçekte ürettiği laboratuvar yapımı mücevher taşı hangisidir?', 'Sentetik yakut', ['Sentetik elmas', 'Kültür incisi', 'Sentetik zümrüt'], 'Verneuil yöntemi, alüminyum oksit tozunun alevde eritilip bir tohumun üzerinde damlatılarak kristal büyütülmesine dayanır; yöntem bugün de kullanılmaktadır.'),
  ('Elmasın sertliği çok yüksek olmasına rağmen yere düşürüldüğünde kırılabilmesinin nedeni nedir?', 'Belirli yönlerde ayrılma (klivaj) düzlemleri bulunması', ['Çok yumuşak bir mineral olması nedeniyle darbede ezilip dağılması', 'İçinin sıvı dolu olması', 'Metal içermesi'], 'Sertlik çiziğe dayanıklılığı gösterir, ancak sağlamlık değildir; elmasın kristal yapısında düzlemler vardır ve darbe bu doğrultuda ayrılma yaratır.'),
  ('Mücevher yapımında platinin altına göre tercih edilmesinin teknik bir nedeni nedir?', 'Çok dayanıklı ve nadiren kararması, taşları sıkı tutması', ['Altından çok daha hafif ve yumuşak olması, böylece kolay işlenmesi', 'Altından daha parlak sarı renkte olması', 'Altından daha ucuz olması'], 'Platin yoğun, sert ve ağır bir metaldir; zamanla rengi değişmez. Bu özellikler özellikle elmas gibi değerli taşların tırnaklarda sağlam tutulmasını sağlar.'),
  ('Kuyumcuların ağırlık birimi olarak kullandığı \'dirhem\' kaç gram civarındadır (Osmanlı\'da standartlaşmış değer)?', 'Yaklaşık 3,2 gram', ['Yaklaşık 12 gram', 'Yaklaşık 0,5 gram', 'Yaklaşık 100 gram'], 'Osmanlı dirhemi yaklaşık 3,2 gramdır ve kuyumculukta altın-gümüş tartımında uzun süre kullanılmıştır.'),
  ('Altın tozunun saf altına dönüştürülmesinde tarihte kullanılan \'kupelasyon\' yöntemi neyi sağlar?', 'Altın ya da gümüşü kurşun ve diğer metallerden arıtmayı', ['Altını camla birleştirip renkli bir hamur elde etmeyi', 'Gümüşü renklendirmeyi', 'Altını eritmeden şekillendirmeyi'], 'Kupelasyonda kurşunlu alaşım kemik külü bir kapta ısıtılır; kurşun ve diğer metaller oksitlenip emilir, geriye saf altın ya da gümüş kalır.'),
  ('Anni Albers\'in Bauhaus\'ta dokuma atölyesinde gelişen ve sonradan Black Mountain College\'da sürdürdüğü çalışmaların ana görüşü nedir?', 'Dokumayı modern sanat ve tasarım disiplini olarak yüceltmek', ['Dokumayı resimden ayrı tutup yalnızca bir zanaat olarak sürdürmek', 'Dokumayı tamamen sanayi üretimine bırakıp el işçiliğini bitirmek', 'Dokumayı resimden ayırmak'], 'Albers, dokumayı görsel sanatla eşdeğer bir ifade biçimi olarak yorumladı; malzeme ve yapı üzerine yazıları tekstil tasarımını kuramsal bir alan hâline getirdi.'),
  ('Polonyalı sanatçı Magdalena Abakanowicz\'in 1960\'larda ürettiği, sisal ve keten gibi liflerden yapılan büyük boyutlu asılı heykelimsi dokumalara ne ad verilir?', 'Abakanlar', ['Gobelenler', 'Kilimler', 'Paisley'], 'Abakanowicz dokumayı duvardan kopararak üç boyutlu, mekânı kuşatan organik biçimlere dönüştürdü; çalışmalar \'Abakan\' adıyla tanınır ve \'lif sanatı\' akımının öncüsüdür.'),
  ('Optik camın bilimsel üretimini başlatan, 1884\'te Jena\'da Zeiss ile birlikte çalışmaya başlayan Alman kimyager kimdir?', 'Otto Schott', ['Frederick Carder', 'Émile Gallé', 'Harvey Littleton'], 'Schott, borosilikat ve çeşitli optik camları geliştirerek mikroskop ve teleskop lenslerinin kalitesini yükseltti; Jena Cam Çalışmaları bunun ürünüdür.'),
  ('Venedik\'in \'conterie\' denilen küçük cam boncukları tarihte hangi ticarette önemli rol oynamıştır?', 'Afrika ve Amerika ile yapılan takas ticaretinde', ['Çin\'den Avrupa\'ya yapılan ipek ve porselen ticaretinde ödeme aracı olarak', 'Bizans döneminde Baltık kıyılarından kehribar alımında vergi olarak', 'Bizans silah ticaretinde'], 'Venedik cam boncukları, 15-19. yüzyıllarda Afrika\'ya ve Amerika\'ya ticaret mallarıyla birlikte gönderilmiş, yerel halklarca değerli takı sayılmıştır.'),
  ('Camın erime noktasının kesin bir değeri olmayıp yumuşama aralığı göstermesi, camı hangi kavramla ilişkilendirir?', 'Amorf yapı ve camsı geçiş', ['Kristalleşme', 'Sublimleşme', 'İyonlaşma'], 'Amorf katılar belirli bir erime noktasında değil, bir sıcaklık aralığında yumuşar; bu özellik camın üflenerek biçimlendirilmesini mümkün kılar.'),
  ('Bir fabrika, şişe camını yeşil yerine renksiz yapmak istiyor. Hammaddede hangi iyileştirmeye gider?', 'Demir içeriği düşük, saf silis kumu kullanır', ['Renkli kırık cam (cullet) oranını artırarak', 'Daha çok demir ekleyerek camın rengini koyulaştırır', 'Bakır tozu ekler'], 'Renksiz cam için demir safsızlığı en aza indirilir; kalan yeşilimsi ton ise mangan ya da selenyumla giderilebilir.'),
  ('Kaare Klint\'in Danimarka modern mobilya tasarımına temel katkısı nedir?', 'Mobilyayı insan bedeni ölçülerine ve kullanım ihtiyaçlarına göre sistemli biçimde tasarlaması', ['Mobilyayı yalnızca süsleme zenginliğine ve oymaya göre tasarlaması', 'Mobilyada yalnızca plastik ve çelik kullanıp ahşabı reddetmesi', 'Mobilyayı tamamen Çin üslubunda yapması'], 'Klint, insan ölçüleri ve eşyaların boyutlarını inceleyerek tasarım yapan bir yaklaşım getirdi; \'Danimarka modernizminin babası\' sayılır.'),
  ('George Nelson\'ın 1945\'ten itibaren sanat yönetmenliğini yaptığı ve Eames, Noguchi gibi tasarımcılarla çalışan Amerikan mobilya firması hangisidir?', 'Herman Miller', ['Knoll', 'Thonet', 'Vitra'], 'Herman Miller, Nelson\'ın yönetiminde modernist tasarımı Amerikan ofis ve evlerine taşıdı; Nelson\'ın \'Marshmallow\' kanepesi de bu çalışmaların ürünüdür.'),
  ('Westminster Abbey\'de bulunan ve İngiliz hükümdarlarının taç giymesinde kullanılan, yaklaşık 1300\'de yaptırılan ahşap tahtın adı nedir?', 'Edward Tahtı (Coronation Chair)', ['Peacock (Tavus Kuşu) Tahtı (Babür ve İran hükümdarlarının mücevherli tahtı)', 'Savonarola (X biçimli bacaklı Rönesans katlanır koltuğu)', 'Windsor sandalyesi (18. yüzyıl İngiliz kırsal sandalyesi)'], 'Edward Tahtı, I. Edward tarafından Scone Taşı\'nı barındırmak için yaptırıldı; yüzyıllardır taç giyme törenlerinde kullanılır.'),
  ('6. yüzyıl Bizans fildişi oymacılığının en ünlü örneklerinden biri olan ve Ravenna Başpiskoposu\'na ait tahtın adı nedir?', 'Maximianus Tahtı', ['Edward Tahtı', 'Tutankamon Tahtı', 'Cathedra Petri'], 'Maximianus Tahtı, yüzlerce fildişi levhayla kaplıdır; Incil sahneleri ve bitkisel motiflerle doludur.'),
  ('Giza\'daki Hetepheres (Kral Khufu\'nun annesi) mezarında bulunan ve sökülüp yeniden kurulabilen mobilyalar neyi gösterir?', 'Eski Krallık döneminde yüksek düzeyde mobilya işçiliği ve altın kaplamanın bulunduğunu', ['Eski Mısır\'da mobilyanın hiç bilinmediği ve herkesin yere oturduğunu', 'Taşın tek mobilya malzemesi olduğunu ve ahşabın hiç kullanılmadığını', 'Plastiğin kullanıldığını'], 'MÖ 26. yüzyılda altın kaplı yatak, sandalye ve tahtırevan yapılmıştı; geçmeli birleşimlerle sökülebiliyordu.'),
  ('19. yüzyıl Amerika\'sında John Henry Belter\'in kullandığı yöntemin özelliği neydi?', 'Kat kat gül ağacı kaplamayı buharla bükerek oyma motifli mobilya yapması', ['Çelik boruyu bükerek ve kaynaklayarak gergin deri oturaklı koltuk üretmesi', 'Plastik kalıp dökerek tek parça gövdeli sandalye yapması', 'Cam üflemesi'], 'Belter, ince ahşap katmanları yapıştırıp bükerek ve oyarak Rokoko Revival mobilya yaptı; bu laminasyon tekniği sonradan kontrplak üretimine de yol açtı.'),
  ('Bir antikacı, bir sandalyenin bacağında arkadan ve içeriden birbirine uymayan makine kesimli ve elle yontulmuş parçalar görüyor. Bu durum ne anlama gelebilir?', 'Sandalyenin sonradan onarıldığı ya da farklı dönem parçalarının birleştirildiği', ['Sandalyenin hiç kullanılmadığı ve fabrikadan yeni çıktığı', 'Sandalyenin tek parça döküm olarak plastikten üretildiği', 'Sandalyenin tek parça dökümü olduğu'], 'Farklı kesim izleri ve aşınma düzeyleri sonradan eklenen ya da onarılan parçaları gösterir; bu tür \'marriage\' mobilyaların değerini düşürür.'),
  ('Bir koleksiyoncu iki Rokoko komodin arasından hangisinin daha özgün olduğunu anlamak istiyor. Hangi ipucu en önemlidir?', 'Kaplama, bronz süs ve çekmece eklemlerinin dönem tekniklerine uygunluğu', ['Komodinin fiyat etiketi ve mağazadaki ışık düzeni', 'Komodinin boyasının parlaklığı ve kokusu', 'Komodinin üzerindeki eşyaların sayısı ve odadaki yeri'], 'Özgünlük, malzeme, el kesimi eklemler, aşınma ve metal süslerin dönem tekniğine uyup uymadığıyla değerlendirilir.'),
  ('Fenike ve Suriye atölyelerinde yaygın olan, fildişi levhalara oyulan kabartma süslemeler, Nimrud\'daki Asur sarayında nasıl bulunmuştur?', 'Mobilya ve tahtlara gömülü kakma panolar olarak', ['Bir hükümdarın parmağına takılan mühür yüzüğü taşı olarak', 'Savaşçıların kılıç kabzasına gömülen küçük kabartma plakalar olarak', 'Cam kâse olarak'], 'Nimrud\'da bulunan Fenike fildişi levhaları, Asur saray mobilyalarını süslemek için ithal edilmiş ya da yağma yoluyla alınmıştı; Mısır ve Suriye etkilerini taşır.'),
  ('Gordion\'daki Midas Tümülüsü\'nde bulunan Frig mobilyasının özelliği hangisidir?', 'Zıvana birleşimli, geometrik kakmalı servis masaları', ['Çelik borudan bükülmüş, deri gerilmiş hafif sandalyeler', 'Cam levha kaplı, metal kenarlı seri üretim dolaplar', 'Plastik koltuklar'], 'Gordion\'daki MÖ 8. yüzyıl mobilyaları, ceviz ve ardıç ağacından geometrik kakmalı ve geçmeli yapılmıştır; Anadolu\'daki en eski ahşap mobilya örnekleridir.'),
  ('Hitit sanatında hayvan başı biçimli, ritüel içki kabına verilen ad nedir?', 'Rhyton', ['Krater', 'Amphora', 'Lekythos'], 'Rhyton, hayvan başı ya da boynuz biçimli içki kabıdır; Hititlerde ve Hellenistik dünyada ritüel ve şölenlerde kullanıldı.'),
  ('Antik Yunan\'da Athena Parthenos heykelinin kaplama tekniğiyle ilgili olarak, \'krizelefantin\' hangi malzemelerin birlikte kullanılmasını anlatır?', 'Fildişi ve altın', ['Bronz ve gümüş', 'Mermer ve cam', 'Ahşap ve bakır'], 'Krizelefantin heykellerde ahşap ya da taş çekirdeğin üzerine, ten bölümlerine fildişi, giysi ve takılara altın levha uygulanır; Phidias\'ın Athena ve Zeus heykelleri bu yöntemle yapılmıştı.'),
  ('Roma\'da \'terra sigillata\'nın imparatorluk çapında yayılmasının başlıca nedeni nedir?', 'Standart kalıpla üretilip ticaret yoluyla yayılan ucuz ama zarif sofra kapları olması', ['Yalnızca imparatorun sofrasında kullanılan, çok pahalı özel bir altın kap olması', 'Yalnızca madencilik bölgelerinde üretilip yerel olarak tüketilmesi', 'Tamamen altından yapılması'], 'Terra sigillata kalıpla basılıp fabrikalarda seri üretilirdi; ihracat ağı İspanya\'dan Britanya\'ya uzanıyordu.'),
  ('Bir arkeolog, hayvan başı biçimli bir kabın (rhyton) alt ucunda küçük bir delik görüyor. Bu delik ne işe yarar?', 'Sıvının ince bir akışla boşaltılmasına', ['Kabın içine ışık girmesine ve içeriğin görünmesine', 'Kabın pişirme sırasında havalandırılmasına ve çatlamamasına', 'Kabın boyanmasına'], 'Rhyton\'un uç kısmındaki küçük delikten içki ince akışla ağıza akıtılırdı; kabı bu yüzden yere koymadan içilirdi.'),
  ('Johann Joachim Kändler\'in Meissen\'deki başlıca rolü nedir?', 'Başmodelci olarak porselen figür ve hayvan heykelleri ile servis tasarımları yapması', ['Cam ayna üretim atölyesinin yöneticisi olarak Venedik ustalarını işe alması', 'Gobelen kartonlarını çizip dokumacılara dağıtması', 'Kuyumcubaşı olarak saray mücevherlerinin tasarımını yapması'], 'Kändler 1731\'den itibaren Meissen\'de hayvan heykelleri, rokoko figürleri ve Kuğu Servisi gibi büyük takımları modelleyerek manufakturanın üslubunu belirledi.'),
  ('Meissen\'in kuruluş aşamasında Böttger\'in 1707 civarında ürettiği ilk seramik ürün neydi?', 'Kırmızı taş hamur', ['Mavi sırlı, kalay sırlı Delft çanak çömleği', 'Beyaz, saydam ve yüksek ısıda pişen sert hamurlu porselen', 'Yumuşak hamurlu, sırsız bisküvi figürler'], 'Böttger, beyaz porselenden önce sert, kırmızı bir taş hamur geliştirdi; bunu 1708-09\'da beyaz porselen izledi.'),
  ('Sèvres porselenlerinde 18. yüzyılda çok aranan pembe renge verilen ad nedir?', 'Rose Pompadour', ['Bleu céleste', 'Bleu de roi', 'Jaune jonquille'], 'Madame de Pompadour\'un adıyla anılan pembe zemin, 1757\'den sonra Sèvres\'in özel renklerinden biri oldu; diğerleri mavi tonlarıdır.'),
  ('19. yüzyılda Minton\'un geliştirdiği, mermer görünümlü sırsız porselen heykel malzemesi hangisidir?', 'Parian', ['Jasperware', 'Majolika', 'Creamware'], 'Parian, ismini Paros mermerinden alır; sırsız ve hafif mat yüzeyi mermer heykelleri taklit ederek orta sınıf evlerinde yaygın küçük heykel olarak kullanıldı.'),
  ('Josiah Wedgwood\'un 1769\'da kurduğu ve işçilerin yakınında yaşadığı fabrikaya hangi ad verilmiştir?', 'Etruria', ['Meissen', 'Sèvres', 'Delft'], 'Etruria, Etrüsk vazolarına duyulan hayranlıktan adını alır; Wedgwood fabrikayı sanayi ve işçi konutlarıyla birlikte kurmuş, seri üretimi disipline etmiştir.'),
  ('Wedgwood\'un 1790\'larda Portland Vazosu\'nu taklit etmesi, bu seramik fabrikası için hangi sonucu doğurmuştur?', 'Jasperware ile klasik eserleri ticari ürüne dönüştürme becerisinin kanıtlanması', ['Fabrikanın kapanması ve Wedgwood\'un iflas etmesi', 'Çin ithalatının artması ve porselen fiyatlarının yükselmesi', 'Porselen üretiminin yasaklanması ve fabrikaların kapatılması'], 'Wedgwood, Roma cam vazosunun benzerini sırsız taş hamuruyla birçok kez yapmış, böylece tekniğini başarıyla göstermiş; Portland Vazosu kopyaları ünlüdür.'),
  ('Seramikte \'bisküvi (biscuit)\' porselen figürlerin Sèvres\'te revaçta olmasının nedeni nedir?', 'Sırsız yüzeyin mermer gibi pürüzsüz ve ince detayları gösterebilmesi', ['Boyanın çok parlak olması ve cam gibi ışık geçirmesi', 'Yüzeyin cam kaplı olması ve parlak yansıma vermesi', 'Figürlerin saydam olması ve içlerinin görünmesi'], 'Sırsız porselen, ışığı mat yansıtır ve heykelsi ayrıntıları net gösterir; Pigalle gibi sanatçıların modelleri bu şekilde üretildi.'),
  ('Bir seramik uzmanı, sırın altında ince, kafes biçimli çatlaklar ve eski dolgu izleri görürse ne düşünür?', 'Parçanın eski olabileceğini ve onarım geçirdiğini', ['Parçanın yakın zamanda yapıldığı ve hiç kullanılmadığı sonucuna', 'Parçanın camdan yapıldığı ve sırrın boyayla taklit edildiği sonucuna', 'Parçanın hiç boyanmadığı ve sırsız bırakıldığı sonucuna'], 'Craquelé zamanla ve sır-hamur uyumsuzluğundan oluşur; onarım izleri de kullanım geçmişini gösterir. Ancak sahte craquelé yapılabildiğinden tek başına yeterli kanıt değildir.'),
  ('16. yüzyılda Sen no Rikyū\'nün çay anlayışına uygun siyah ve kırmızı elle biçimlendirilmiş çay kâseleri üreten ve Raku ailesinin kurucusu sayılan çömlekçi kimdir?', 'Chōjirō', ['Hamada', 'Hon\'ami Koetsu', 'Kitaōji Rosanjin'], 'Chōjirō, çarkta değil elle şekillendirilen siyah ve kırmızı Raku kâselerini üretti; sade ve kendiliğinden güzelliği öne çıkaran bu çay kâseleri Raku ailesinin geleneğidir.'),
  ('Hollandalıların Portekiz gemilerinden ele geçirip Avrupa\'da sattığı ve \'Kraak\' adıyla anılan Çin ihracat porselenlerinin adı hangi sözcükten türemiştir?', 'Carrack (büyük Portekiz ticaret gemisi)', ['Craquelé (sır yüzeyindeki ince çatlak ağı)', 'Karat (mücevher ağırlık ölçüsü)', 'Kraft (kahverengi ambalaj kâğıdı türü)'], 'Kraak porseleni, Portekiz karaklarından ele geçirilen mavi-beyaz paneller ve dilimli kenarlı tabaklardır; 17. yüzyıl Hollanda natürmortlarında sık görülür.'),
  ('Rusya\'da ağaç kaşık, kâse ve mobilyaların kırmızı, siyah ve altın renkli bitkisel motiflerle süslenmesini sağlayan geleneksel boyama tekniği hangisidir?', 'Khokhloma', ['Gzhel', 'Palekh', 'Fedoskino'], 'Khokhloma ahşap eşyayı gümüş ya da kalay tozu sürtüp yağlı vernikle fırınlayarak altın görünüm verir; kırmızı ve siyah desenler üzerine uygulanır.'),
  ('Palekh köyünün lake minyatür kutuları nasıl yapılır?', 'Papye-maşe kutuların siyah zemin üzerine yumurta tempera boyayla ve altın ayrıntılarla boyanması', ['Cam tozunun kalıpta fırınlanarak şeffaf kutu yapılması', 'Metalin kalıba dökülüp üzerine mine uygulanması', 'Ahşap kutunun sedef ve fildişi parçalarla kaplanması'], 'Palekh ustaları ikon ressamlığı geleneklerini lake kutulara taşıdı; siyah zemin üzerinde masal ve halk sahnelerini ince fırçayla resmettiler.'),
  ('İç içe geçen ahşap Rus bebeklerine (matruşka) ilk kez 1890\'larda biçim veren sanatçı ve atölye çevresi hangisidir?', 'Abramtsevo (Malyutin) çevresi', ['Fabergé atölyesi', 'Gzhel köyü', 'Kremlin silah atölyesi'], 'Matruşka, Moskova yakınındaki Abramtsevo sanat topluluğunda Sergey Malyutin\'in tasarımıyla Japon bir bebekten esinlenerek ortaya çıkmıştır.'),
  ('Bir müşteri, taşın gerçek elmas olup olmadığını anlamak için taşa nefesiyle buğu yapıyor ve buğunun hemen kaybolup kaybolmadığını gözlüyor. Bu basit testin dayanağı nedir?', 'Elmasın ısıyı çok iyi iletmesi nedeniyle buğunun çok çabuk dağılması', ['Elmasın suyu emmesi', 'Elmasın renk değiştirmesi', 'Elmasın manyetik olması'], 'Elmas, ısıyı çok iyi ileten bir maddedir; buğu hemen dağılır. Cam ya da kübik zirkonya ise buğuyu daha uzun süre tutar. Güvenilir kanıt için gemolojik cihazlar gerekir.'),
  ('Bir inci kolyenin gerçek ya da taklit olduğunu anlamak için hafifçe dişe sürtmek ne tür bir gözlem verir?', 'Gerçek inci pürüzlü, kumlu bir his; taklit ise pürüzsüz ve camsı bir his verir', ['Gerçek inci hiç his vermez', 'Taklit inci eriyip dağılır', 'Gerçek inci kırılır'], 'Gerçek inci sedef katmanları nedeniyle çok ince bir pürüz hissi verir; cam ya da plastik taklit ise pürüzsüzdür. Bu yalnız basit bir ön testtir.'),
  ('Seramikte sırın hamurdan daha çok büzülmesi hâlinde yüzeyde ince çatlak ağının oluşması neyle açıklanır?', 'Sır ile hamurun genleşme katsayılarının uyumsuz olması', ['Hamurun çok beyaz olması', 'Fırının kapalı kalması', 'Boyanın çok parlak olması'], 'Pişme sonrası soğurken sır, hamurdan fazla büzülürse gerilim altında çatlar (crazing); sır daha az büzülürse soyulma (shivering) görülür.'),
  ('Seramikçi, sırın hamurdan daha az büzülmesi nedeniyle sırın kenarlardan soyulduğunu fark ediyor. Bu kusura ne denir?', 'Shivering (sır soyulması)', ['Crazing (sır çatlağı)', 'Pinholing (iğne deliği)', 'Crawling (sır sürünmesi)'], 'Sırın büzülmesi hamurdan azsa sır sıkışır ve kenarlarda pul pul ayrılır; crazing ise tersi durumdur.'),
  ('Bir tasarımcı, Arts and Crafts hareketinin \'sanat ile zanaat arasında hiyerarşi yoktur\' görüşünü Rönesans\'tan beri süren hangi anlayışa karşı savunmaktadır?', 'Güzel sanatların (resim, heykel, mimarlık) dekoratif sanatlardan üstün sayıldığı hiyerarşiye', ['Resmin yasak sayılmasına', 'Seramiğin yalnız Çin\'e özgü sayılmasına', 'Fotoğrafın sanat sayılmamasına'], 'Rönesans\'tan beri resim, heykel ve mimarlık \'yüksek sanat\' sayılırken mobilya, tekstil ve seramik \'küçük sanat\' olarak görüldü; Morris bu ayrımı reddetti.'),
  ('Bir müze küratörü, Çin ve Japon seramiklerinin Avrupa\'da taklit edilmesinin sanat tarihi açısından önemini nasıl açıklar?', 'Üslupların ve tekniklerin kültürler arasında dolaşımını ve yeni sentezleri göstermesi', ['Avrupa\'nın hiçbir şey öğrenmediğini', 'Çin seramiğinin yasak olduğunu', 'Seramiğin yalnız Avrupa\'da icat edildiğini'], 'Meissen ve Delft gibi merkezler Doğu seramiğini taklit ederken kendi teknik ve estetiklerini geliştirdi; böylece kültürler arası etkileşim somut örneklenir.'),
  ('Çin sanatında \'yeşim\' denince ağırlıklı olarak hangi mineral kastedilir?', 'Nefrit', ['Zümrüt', 'Korindon', 'Granat'], 'Çin yeşimi çoğunlukla nefrittir (amfibol grubu); Orta Amerika\'da ise jadeit kullanılmıştır. İkisi farklı minerallerdir ama \'yeşim\' diye anılır.'),
  ('Avustralya\'nın ünlü mücevher taşı opal su içerir. Bu özellik, taşın bakımı için neyi gerektirir?', 'Kurumaya ve çatlamaya karşı aşırı ısıdan ve çok kuru ortamdan korunmasını', ['Güneşte uzun süre bekletilmesini', 'Kuru ve sıcak saklanmasını', 'Aşırı sıcak suda yıkanmasını'], 'Opal %3-21 arası su içerir; aşırı kuruma ve ısı çatlamalara neden olabilir. Bu yüzden opal takılar ısıdan ve kuru ortamdan korunur.'),
  ('Alexandrit gibi bazı mücevher taşlarının gün ışığında yeşil, akkor lamba ışığında kırmızımsı görünmesine ne ad verilir?', 'Renk değiştirme', ['Asterizm', 'Kabaşon etkisi', 'Klivaj'], 'Alexandrit, ışık kaynağının tayfına göre renk değiştirir; gün ışığında mavi-yeşil, akkor lambada kırmızıya döner. Bu özellik taşı nadir ve değerli kılar.'),
  ('Bir mücevher taşı mavi, yeşil ve sarı gibi birden çok rengi, farklı açılardan bakınca farklı tonda gösteriyor. Bu özellik hangi terimle bilinir?', 'Pleokroizm', ['Asterizm', 'Fosforesans', 'Dispersiyon'], 'Pleokroizm, kristalin farklı yönlerde ışığı farklı soğurmasıyla ortaya çıkar; turmalin, kordiyerit ve zümrüt gibi taşlarda belirgindir.'),
  ('Bir kuyumcu \'altın doldurulmuş\' (gold-filled) ve \'altın kaplama\' takıyı ayırt ediyor. En belirgin fark nedir?', 'Altın doldurulmuş ürünlerde altın tabakası çok daha kalın ve dayanıklıdır', ['İkisi tamamen aynıdır; yalnızca etiket adları farklıdır', 'Altın kaplamada altın tabakası daha kalın ve ısıyla bağlanmıştır', 'İkisinde de altın bulunmaz; yalnızca altın renkli boya sürülmüştür'], 'Altın doldurulmuş takıda altın tabakası mekanik olarak ısıyla bağlanır ve ağırlıkça en az %5 içerir; kaplamada ise çok ince bir elektrolitik tabaka bulunur.'),
  ('Bir müşteri, aynı ağırlıkta iki altın yüzük karşılaştırıyor: biri 14 ayar, diğeri 18 ayar. 18 ayarlı yüzüğün altın içeriği 14 ayarlıya göre hangi oranda yüksektir (yaklaşık)?', 'Yaklaşık 1,28 kat', ['Yaklaşık 2 kat', 'Yaklaşık 1,05 kat', 'Yaklaşık 4 kat'], '750 ÷ 585 ≈ 1,28; yani 18 ayarlı yüzük aynı ağırlıkta yaklaşık yüzde 28 daha fazla saf altın içerir.'),
  ('Bir kuyumcu 10 gram 14 ayar altını eritip üzerine 5 gram saf altın katıyor. Yeni alaşımın altın oranı yaklaşık kaç binde olur?', 'Yaklaşık 723', ['Yaklaşık 585', 'Yaklaşık 750', 'Yaklaşık 667'], 'Saf altın = 10×0,585 + 5 = 10,85 gram; toplam 15 gram. Oran = 10,85/15 ≈ 0,7233; yani yaklaşık binde 723 (17,4 ayar).'),
  ('Denizli\'nin bir ilçesinde el tezgâhlarında dokunan, hafif pamuklu ve ipek karışımlı bezlerle ünlü geleneksel dokuma hangisidir?', 'Buldan dokuması', ['Şile bezi', 'Kutnu', 'Çatma'], 'Buldan, Ege\'de el dokumacılığının önemli merkezidir; ince ve çizgili bezlerinden gömlek, çarşaf ve masa örtüsü yapılır.'),
  ('Bir tasarımcı, kumaş desenini çok geniş bir rapportla bastırmak yerine çok küçük rapportla yapmak istiyor. Bu durumda hangi sonuç olasıdır?', 'Desen daha sık ve düzgün tekrar eder, kumaştan fire azalır', ['Desen hiç tekrar etmez', 'Kumaş şeffaf olur', 'Kumaş her yerde farklı görünür'], 'Küçük rapport, desen birimi küçük olduğundan kesim ve kenarda daha az fire verir; büyük rapportta ise desen eşleştirmesi için daha çok kumaş harcanır.'),
  ('Bir tasarımcı, bir yün kilimin desenini tezgâhta uygularken çözgü sıklığını artırırsa desende hangi değişiklik beklenir?', 'Daha ince çizgiler ve küçük motifler yapılabilir', ['Desen kaybolur', 'Kilim havlı olur', 'Kilim düğümlü olur'], 'Çözgü sıklığı arttıkça kilim dokuması daha ince desenlere izin verir; ancak kilim yine havsız bir dokuma olarak kalır.'),
  ('Orkney Adaları\'ndaki Neolitik Skara Brae yerleşiminin mobilya tarihi bakımından önemi nedir?', 'Taştan yapılmış dolap, yatak ve raf gibi yerleşik mobilyaların korunmuş olması', ['Çelik mobilyaların bulunması', 'Cam kaplı dolapların bulunması', 'Plastik koltukların bulunması'], 'Skara Brae\'de ağaç az olduğundan evlerde taş dolaplar, yataklar ve ocaklar yapılmış; MÖ 3000 dolayına ait bu eşyalar korunmuştur.'),
  ('Güney Afrika\'daki Blombos Mağarası\'nda yaklaşık 75.000 yıl öncesine ait olduğu düşünülen deniz kabuğu boncukları neden önemlidir?', 'Bilinen en eski takı örneklerinden biri sayılmaları', ['Roma çağı mücevheri olmaları', 'Altın işçiliğinin ilk örnekleri olmaları', 'Cam boncukların atası olmaları'], 'Delikli deniz kabuğu boncukları, insanların çok erken bir dönemde kendini süsleme ve sembolik düşünme yeteneğini gösterir; bu nedenle takıların en eski örneklerindendir.'),
  ('Gürcistan\'daki Dzudzuana Mağarası\'nda bulunan yaklaşık 30.000 yıllık boyalı yabani keten lifleri hangi bilgiyi verir?', 'İnsanların lifi iplik ve örgü için çok erken kullandığını', ['Camın o dönemde bilindiğini', 'Seramik fırının o dönemde bulunduğunu', 'Altının işlendiğini'], 'Boyalı ve bükülmüş lifler, Üst Paleolitik\'te bile iplik ve giysi üretiminin yapıldığını gösterir; tekstilin kökeni sanılandan eskidir.'),
  ('Romalı yazar Yaşlı Plinius\'a göre camın ilk kez nasıl bulunduğu anlatılır?', 'Natron taşıyan Fenikeli tüccarların kumsalda ateş yakmasıyla', ['Bir Mısır firavununun sarayında', 'Bir Roma imparatorunun fırınında', 'Bir Çin seramikçisinin denemesiyle'], 'Plinius, Fenikeli denizcilerin natron kütlelerini ocak taşı yapınca kumun erimesini anlatır; bu hikâye bir efsanedir, cam daha önce Mezopotamya\'da üretiliyordu.'),
  ('Ur Kraliyet Mezarları\'ndan çıkan altın başlık ve boncuklar, MÖ 3. binyıl Mezopotamya\'sında hangi toplumsal durumu gösterir?', 'Zengin bir yönetici sınıfın ve uzman kuyumcu atölyelerinin varlığını', ['Herkesin eşit servete sahip olduğunu', 'Altının bilinmediğini', 'Madenciliğin yasak olduğunu'], 'Çok sayıda altın, lapis ve karnelyan, uzak ticaret yollarını ve usta atölyelerini; böylece sınıflı bir toplumu gösterir.'),
  ('Lapis lazuli taşının Mezopotamya ve Mısır mücevherlerinde bulunması, hangi ticaret ağına işaret eder?', 'Afganistan\'daki madenlerden yola çıkan uzak mesafe ticaretine', ['Yalnızca yerel pazarlara', 'Atlantik ticaretine', 'Çin ipek yoluna'], 'Lapis lazuli\'nin bilinen en eski kaynağı Afganistan\'ın Badahşan bölgesidir; taş binlerce kilometre taşınarak Sümer ve Mısır takılarına girmiştir.'),
  ('Bir cam koleksiyoncusu, bir şişedeki \'çekirdek\' izlerini ve renkli sarmal çizgileri görüyor. Bu özellik, şişenin yapım tekniği hakkında ne söyler?', 'Çekirdek üzerine sarılan sıcak camla yapıldığını', ['Kalıp üflemeyle yapıldığını', 'Lazerle kesildiğini', 'Float yöntemiyle üretildiğini'], 'Çekirdek tekniğinde renkli cam ipliği çekirdek etrafına sarılıp tarakla süs verilir; ürünlerde sarmal ve zikzak çizgiler görülür.'),
];
